const dados = $('dados').item.json;
const text = $('message1').item.json.message || '';

const entry = {
  message_id: dados.id || null,
  conversation_id: `${dados.instance}|${dados.remotejid}`,
  contact_name: dados.pushName || null,
  is_support: false,
  message_text: text,
  message_timestamp: new Date().toISOString(),
};

return [{ json: { log_entry: JSON.stringify(entry) } }];

function esc(s) {
  if (s === null || s === undefined) return 'NULL';
  return "'" + String(s).replace(/'/g, "''") + "'";
}

const mensagens = $json.messages || [];

const entries = mensagens
  .map((s) => {
    try {
      return JSON.parse(s);
    } catch (e) {
      return null;
    }
  })
  .filter((e) => e && e.message_text);

if (entries.length === 0) {
  return [{ json: { sql_query: null, count: 0, entries: [] } }];
}

const values = entries
  .map(
    (e) =>
      `(${esc(e.message_id)}, ${esc(e.conversation_id)}, ${esc(e.contact_name)}, ${e.is_support ? 'TRUE' : 'FALSE'}, ${esc(e.message_text)}, ${esc(e.message_timestamp)})`
  )
  .join(',\n');

const sqlQuery = `INSERT INTO support_messages (message_id, conversation_id, contact_name, is_support, message_text, message_timestamp)
VALUES
${values}
ON CONFLICT (message_id) DO NOTHING;`;

return [{ json: { sql_query: sqlQuery, count: entries.length, entries } }];

const rows = $('Preparar Inserts em Lote').item.json.entries;
const SESSION_GAP_MINUTES = 30;

const byConversation = {};
for (const row of rows) {
  (byConversation[row.conversation_id] ||= []).push(row);
}

const sessions = [];

for (const [conversationId, msgs] of Object.entries(byConversation)) {
  msgs.sort((a, b) => new Date(a.message_timestamp) - new Date(b.message_timestamp));

  let current = null;
  for (const m of msgs) {
    const ts = new Date(m.message_timestamp).getTime();
    if (!current || ts - current.lastTs > SESSION_GAP_MINUTES * 60 * 1000) {
      current = {
        conversation_id: conversationId,
        contact_name: m.contact_name,
        lines: [],
        lastTs: ts,
      };
      sessions.push(current);
    }
    current.lines.push(`${m.is_support ? 'Suporte' : 'Cliente'}: ${m.message_text}`);
    current.lastTs = ts;
  }
}

// Descarta sessões com uma única mensagem (não há pergunta+resposta pra aprender)
return sessions
  .filter((s) => s.lines.length >= 2)
  .map((s) => ({
    json: {
      conversation_id: s.conversation_id,
      contact_name: s.contact_name,
      transcript: s.lines.join('\n'),
    },
  }));

const responses = $input.all().map((i) => i.json);
const sessions = $('Agrupar em Sessões de Atendimento').all().map((i) => i.json);

const output = [];

for (let i = 0; i < responses.length; i++) {
  const session = sessions[i];
  const raw = responses[i]?.output || '{"items": []}';
  const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    parsed = { items: [] };
  }

  const items = Array.isArray(parsed.items) ? parsed.items : [];
  for (const qa of items) {
    if (!qa.question || !qa.answer) continue;
    output.push({
      json: {
        question: String(qa.question).trim(),
        answer: String(qa.answer).trim(),
        category: qa.category || 'geral',
        source_conversation_id: session.conversation_id,
      },
    });
  }
}

return output;
